const promisify = (fn) => (...args) =>
  new Promise((resolve, reject) => {
    fn(...args, (error, value) => (error ? reject(error) : resolve(value)));
  });

function split(text, separator, callback) {
  if (typeof text !== "string") {
    throw new TypeError("not text");
  }
  callback(null, text.split(separator), text.length);
}

const splitAsync = promisify(split);
splitAsync("a-b-c", "-").then((value) => console.log(value.join("+")));
splitAsync(42, "-").catch((error) => console.log(error.name));
console.log("called both");
